	private void sizeDiagnostics() {
		String nonDistinct = query.replaceFirst("(?i)SELECT\\s+DISTINCT", "SELECT");
		String[] names = { "fe_tick_queue", "bpkg", "fe_host", "fe_host_cluster", "fe_host_stage", "tp_host",
				"tp_host_cluster", "tp_host_stage", "exbyte", "procmgr_name" };
		LongHashSet hashes = new LongHashSet();
		long rows = 0;
		long start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(nonDistinct).evaluate()) {
			while (result.hasNext()) {
				BindingSet bs = result.next();
				long h = 0xcbf29ce484222325L;
				for (String name : names) {
					Value v = bs.getValue(name);
					h = mix(h, v == null ? 0x9E3779B97F4A7C15L : hash64(v.toString()));
				}
				hashes.add(h);
				if (++rows % 10_000_000 == 0) {
					System.out.println("[diag] non-DISTINCT rows so far: " + rows + ", distinct so far: "
							+ hashes.size() + ", " + secondsSince(start) + " s");
				}
			}
		}
		System.out.println("[diag] non-DISTINCT rows total: " + rows + ", distinct rows (hash): " + hashes.size()
				+ ", stream time " + secondsSince(start) + " s");
		long distinctEstimate = hashes.size();
		hashes = null;

		Runtime rt = Runtime.getRuntime();
		System.gc();
		long baseline = rt.totalMemory() - rt.freeMemory();
		long emitted = 0;
		start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				result.next();
				if (++emitted % 1_000_000 == 0) {
					System.gc();
					long used = rt.totalMemory() - rt.freeMemory() - baseline;
					System.out.println("[diag] DISTINCT emitted " + emitted + ", retained heap " + (used >> 20)
							+ " MiB, " + (used / emitted) + " B/row, " + secondsSince(start) + " s");
				}
			}
			System.out.println("[diag] DISTINCT completed: " + emitted + " rows in " + secondsSince(start) + " s");
		} catch (OutOfMemoryError e) {
			System.out.println("[diag] DISTINCT OOM after " + emitted + " rows (of ~" + distinctEstimate + ")");
		}
	}

	/** Row count plus order-independent checksums (sum and xor of 64-bit row hashes) of the DISTINCT result. */
	private void checksum() {
		long rows = 0;
		long sum = 0;
		long xor = 0;
		long start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			List<String> names = result.getBindingNames().stream().sorted().toList();
			while (result.hasNext()) {
				BindingSet bs = result.next();
				long h = 0xcbf29ce484222325L;
				for (String name : names) {
					Value v = bs.getValue(name);
					h = mix(h, v == null ? 0x9E3779B97F4A7C15L : hash64(v.toString()));
				}
				rows++;
				sum += h;
				xor ^= h;
			}
		}
		System.out.println("[verify] engine " + engine + " rows=" + rows + " sum=" + Long.toHexString(sum) + " xor="
				+ Long.toHexString(xor) + " time=" + secondsSince(start) + " s");
	}

	private void runCountQueries(Path dir) throws IOException {
		try (java.util.stream.Stream<Path> files = Files.list(dir)) {
			for (Path file : files.filter(p -> p.toString().endsWith(".rq")).sorted().toList()) {
				long start = System.nanoTime();
				try (SailRepositoryConnection connection = repository.getConnection();
						TupleQueryResult result = connection
								.prepareTupleQuery(Files.readString(file, StandardCharsets.UTF_8))
								.evaluate()) {
					while (result.hasNext()) {
						System.out.println("[counts] " + file.getFileName() + " " + result.next() + " ("
								+ secondsSince(start) + " s)");
					}
				}
			}
		}
	}

	private static long secondsSince(long start) {
		return TimeUnit.NANOSECONDS.toSeconds(System.nanoTime() - start);
	}

	private static long hash64(String s) {
		long h = 0xcbf29ce484222325L;
		for (int i = 0; i < s.length(); i++) {
			h ^= s.charAt(i);
			h *= 0x100000001b3L;
		}
		return h;
	}

	private static long mix(long h, long v) {
		h ^= v + 0x9E3779B97F4A7C15L + (h << 6) + (h >>> 2);
		return h * 0xff51afd7ed558ccdL;
	}

	/** Open-addressing set of longs; 0 is mapped to a sentinel-free alternative. */
	private static final class LongHashSet {
		private long[] table = new long[1 << 20];
		private int size;

		void add(long value) {
			if (value == 0) {
				value = 1;
			}
			if (size * 2 >= table.length) {
				grow();
			}
			if (insert(table, value)) {
				size++;
			}
		}

		int size() {
			return size;
		}

		private static boolean insert(long[] t, long value) {
			int mask = t.length - 1;
			int i = (int) (value ^ (value >>> 32)) & mask;
			while (true) {
				long existing = t[i];
				if (existing == 0) {
					t[i] = value;
					return true;
				}
				if (existing == value) {
					return false;
				}
				i = (i + 1) & mask;
			}
		}

		private void grow() {
			long[] next = new long[table.length * 2];
			for (long v : table) {
				if (v != 0) {
					insert(next, v);
				}
			}
			table = next;
		}
	}

	private void openStore() throws IOException {
		query = Files.readString(Path.of(queryFile), StandardCharsets.UTF_8);
		File dir = new File(storeDir + "-" + engine);
		File marker = new File(dir, ".loaded");
		boolean needsLoad = !marker.exists();
		if (needsLoad && dir.exists()) {
			LmdbTestUtil.deleteDir(dir);
		}
		Files.createDirectories(dir.toPath());

		repository = new SailRepository(new LmdbStore(dir, config(engine)));
		if (needsLoad) {
			load();
			Files.writeString(marker.toPath(), dataFile);
		}
	}

	@Setup(Level.Trial)
	public void setup() throws IOException {
		openStore();
		if (Boolean.parseBoolean(planDiagnostics)) {
			writePlans(true);
		}
	}

	private void writePlans(boolean executed) throws IOException {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			System.out.println("[bench] engine " + engine + ", statements in store: " + connection.size());
			Path planFile = Path.of(queryFile + ".plan-" + engine + ".txt");
			String optimized = connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
			Files.writeString(planFile, "# Optimized\n" + optimized + "\n", StandardCharsets.UTF_8);
			System.out.println("[bench] optimized plan written to " + planFile);
			if (!executed) {
				return;
			}

			long start = System.nanoTime();
			String executedPlan = connection.prepareTupleQuery(query)
					.explain(Explanation.Level.Executed)
					.toString();
			long elapsedMs = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
			Files.writeString(planFile, "\n# Executed (" + elapsedMs + " ms)\n" + executedPlan + "\n",
					StandardCharsets.UTF_8, StandardOpenOption.APPEND);
			long rows = count(connection.prepareTupleQuery(query));
			System.out
					.println("[bench] DISTINCT result rows: " + rows + ", explain(Executed) took " + elapsedMs + " ms");
			Files.writeString(planFile, "\n# DISTINCT result rows: " + rows + "\n", StandardCharsets.UTF_8,
					StandardOpenOption.APPEND);
		}
	}

	private static LmdbStoreConfig config(String engine) {
		LmdbStoreConfig config = ConfigUtil.createConfig();
		config.setValueDBSize(4L * 1024 * 1024 * 1024);
		config.setTripleDBSize(4L * 1024 * 1024 * 1024);
		switch (engine) {
		case "classic" -> {
			config.setNativeEvaluationEnabled(false);
			config.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
			config.setDirectAdjacencyEnabled(false);
		}
		case "native" -> {
			config.setNativeEvaluationEnabled(true);
			config.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
			config.setDirectAdjacencyEnabled(false);
		}
		case "native-adjacency" -> {
			config.setNativeEvaluationEnabled(true);
			config.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
			config.setDirectAdjacencyEnabled(true);
		}
		default -> throw new IllegalArgumentException("Unknown engine " + engine);
		}
		// spill to disk only after 200M cached entries, i.e. keep this query in memory
		config.setIterationCacheSyncThreshold(209_715_200L);
		return config;
	}

	private void load() throws IOException {
		String name = dataFile.endsWith(".gz") ? dataFile.substring(0, dataFile.length() - 3) : dataFile;
		RDFFormat format = Rio.getParserFormatForFileName(name)
				.orElseThrow(() -> new IllegalArgumentException("Unknown RDF format for " + dataFile));
		long start = System.nanoTime();
		try (SailRepositoryConnection connection = repository.getConnection();
				InputStream raw = new BufferedInputStream(Files.newInputStream(Path.of(dataFile)), 1 << 20);
				InputStream in = dataFile.endsWith(".gz") ? new GZIPInputStream(raw, 1 << 20) : raw) {
			connection.begin(IsolationLevels.NONE);
			connection.add(in, "", format);
			connection.commit();
		}
		System.out.println("[bench] loaded " + dataFile + " in "
				+ TimeUnit.NANOSECONDS.toSeconds(System.nanoTime() - start) + " s");
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Benchmark
	public long query() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return count(connection.prepareTupleQuery(query));
		}
	}

	private static long count(TupleQuery tupleQuery) {
		long count = 0;
		try (TupleQueryResult result = tupleQuery.evaluate()) {
			while (result.hasNext()) {
				result.next();
				count++;
			}
		}
		return count;
	}
